 [/\b(?:unidades?|unid)\b/iu,'unit'],
 [/\b(?:kgs?|kilogramos?)\b/iu,'kg'],
 [/\b(?:litros?|lts?)\b/iu,'l'],
 [/\b(?:cajas?)\b/iu,'box'],
 [/\b(?:rollos?)\b/iu,'roll'],
 [/\b(?:paquetes?)\b/iu,'pack'],
 [/(?:\bmetros?\s+c[uú]bicos?\b|\bm3\b|\bm³)(?!\p{L})/iu,'m3'],
 [/(?:\bmetros?\s+cuadrados?\b|\bm2\b|\bm²)(?!\p{L})/iu,'m2'],
 [/\b(?:metros?(?!\s+c[uú]bicos?|\s+cuadrados?)|m(?![²³]))\b/iu,'m'],
